import{_ as d,l as i,o as e,c as n,v as o,p as l,x as r,d as s,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"ORM 阻抗失配","description":"","frontmatter":{"title":"ORM 阻抗失配","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/orm-impedance.md","filePath":"cs/orm-impedance.md","lastUpdated":1789023840000}'),E={name:"cs/orm-impedance.md"};function m(A,a,h,_,B,u){const t=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="orm-阻抗失配" tabindex="-1">ORM 阻抗失配 <a class="header-anchor" href="#orm-阻抗失配" aria-label="Permalink to &quot;ORM 阻抗失配&quot;">​</a></h1><div class="epigraph"><p>对象图有身份、继承与导航；关系有键、表与声明查询。把前者硬按进后者，不是翻译错误，是两种模型的阻抗。</p><footer>—— 据 Copeland and Maier 对对象–关系；Ireland et al. 对阻抗失配；Date 对关系与对象对照</footer></div><p><a href="/cs/schema-migration">上一课</a>把模式当版本化脚本。本课不重写 <code>ALTER</code>。缺口是应用层：对象关系映射（ORM）用类表示元组，用导航表示连接。主干坚持声明 SQL；工程上大量代码通过 ORM 发查询。阻抗失配（impedance mismatch）命名这条缝，避免把 N+1 查询当成「数据库慢」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>对象：可变身份、嵌套集合、继承。关系：值、第一范式、集合查询。映射策略：一类一表、一类一层次一张表、具体类一表——各有空列或连接代价。缺口不是选框架，而是<strong>查询形状</strong>：按对象导航 <code>customer.orders</code> 若逐订单懒加载，就是对每个外键一次查询（N+1）。关系侧一句话连接能做完的，对象侧循环会拆碎。</p><p>单元工作（Unit of Work）跟踪脏对象再生成 <code>UPDATE</code>，与保存点、事务边界必须对齐。迁移工具从实体生成 DDL，常忽略 <a href="/cs/normal-forms">依赖理论</a> 的分解质量。</p><p><span class="marginnote">Copeland and Maier 讨论把对象存进关系。阻抗一词借自电路：两种接口能量反射。本课不把 NoSQL 文档当「阻抗消失」——嵌套文档只是把连接预物化，下一课连接池也不解决模型缝。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>显式查询：把需要的图写成一次 JOIN 或窗口，而不是默认懒加载。投影：不要 <code>SELECT *</code> 水合整个对象图。身份映射：同一主键在同一会话不要两份对象。继承映射写进模式，让迁移课的脚本可见，而不是只在注解里。</p><p>ORM 可以发出参数化 SQL，进入后课预编译。它也可以把过程与触发器完全藏起来——调试时必须能看到最终 SQL。</p>',10)),(e(),l(p,null,{default:r(()=>[c(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBJ%5B%22%E5%AF%B9%E8%B1%A1%E5%9B%BE%E5%AF%BC%E8%88%AA%22%5D%20--%3E%20N1%5B%22N%2B1%20%E6%AC%A1%E6%9F%A5%E8%AF%A2%22%5D%0A%20%20REL%5B%22%E5%A3%B0%E6%98%8E%E8%BF%9E%E6%8E%A5%22%5D%20--%3E%20ONE%5B%22%E4%B8%80%E6%AC%A1%E8%AE%A1%E5%88%92%22%5D%0A%20%20MAP%5B%22%E6%98%A0%E5%B0%84%E7%AD%96%E7%95%A5%22%5D%20--%3E%20SCH%5B%22%E8%A1%A8%20%2F%20%E5%88%97%20%2F%20%E7%A9%BA%E5%88%97%22%5D%0A%20%20UOW%5B%22%E5%8D%95%E5%85%83%E5%B7%A5%E4%BD%9C%22%5D%20--%3E%20TX%5B%22%E5%90%8C%E4%B8%80%E4%BA%8B%E5%8A%A1%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>延迟加载与事务：会话关闭后再导航，连接可能已还，对象成「断开」。这与库的隔离快照不是同一层。脏检查生成的 <code>UPDATE</code> 可能覆盖列，与触发器、乐观版本列互相踩。约束仍在库侧生效；ORM 校验只是提前失败，不是完整性来源。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲连接池尺寸公式——下一课。也不把活动记录对仓库模式的宗教争论写入主干。文档库、宽列是后课数据模型族；它们不自动消除图与集合的缝，只是换一种预连接。</p><p>后课默认：对象导航不是查询计划。看到 N+1 先改加载形状，再谈索引。连接池处理的是会话资源，不是阻抗。</p><p>关系查询的单位是语句与计划；对象的单位是身份与指针。翻译层必须显式。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>阻抗来自对象图对关系的结构差，不是某框架的 bug。</li><li>N+1 是导航默认值；声明连接才是原语。</li><li>连接池下一课：会话昂贵，与映射无关却总被混谈。</li><li>出处：Copeland and Maier；Ireland 等；Date。</li></ul>',8))])}const T=d(E,[["render",m]]);export{D as __pageData,T as default};
